    51→/// `stackaddr` and `stacksize` must be valid pointers.
    52→#[unsafe(no_mangle)]
    53→pub unsafe extern "C" fn pthread_attr_getstack(
    54→    _attr: *const u8,
    55→    stackaddr: *mut *mut u8,
    56→    stacksize: *mut usize,
    57→) -> i32 {
    58→    unsafe {
    59→        *stackaddr = 0x700000000000 as *mut u8; // Fake stack base
    60→        *stacksize = 8 * 1024 * 1024; // 8MB stack
    61→    }
    62→    0
    63→}
    64→
    65→/// # Safety
    66→/// `guardsize` must be a valid pointer.
    67→#[unsafe(no_mangle)]
    68→pub unsafe extern "C" fn pthread_attr_getguardsize(_attr: *const u8, guardsize: *mut usize) -> i32 {
    69→    unsafe {
