    96→) -> i64 {
    97→    unsafe { syscall::syscall6(num as u64, arg1, arg2, arg3, arg4, arg5, arg6) as i64 }
    98→}
    99→
   100→// Unwinding stubs (for panic/backtrace)
   101→stub!(_Unwind_Backtrace, i32);
