    80→
    81→// Memory mapping stubs
    82→stub!(mmap64, *mut u8);
    83→stub!(mprotect, i32);
    84→stub!(munmap, i32);
    85→
    86→// Generic syscall - all x86_64 Linux syscalls use at most 6 arguments
