    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("Could not find workspace root");

    let cmd_name = match config.subcommand {
        Subcommand::Build => "build",
        Subcommand::Run => "run",
        Subcommand::Test => "test",
    };

