     1→//! Environment variable support
     2→//!
     3→//! Provides the `environ` symbol and `getenv` function needed by std::env.
     4→
     5→use core::ffi::{CStr, c_char};
     6→
     7→/// Global environment pointer - set during startup by __libc_start_main
     8→#[unsafe(no_mangle)]
     9→pub static mut environ: *const *const c_char = core::ptr::null();
    10→
    11→/// Initialize environ from the environment pointer passed to __libc_start_main
    12→pub fn init(envp: *const *const c_char) {
    13→    unsafe {
    14→        environ = envp;
    15→    }
    16→}
    17→
    18→/// Iterator over environment entries
    19→struct EnvIter(*const *const c_char);
    20→
    21→impl Iterator for EnvIter {
    22→    type Item = &'static CStr;
    23→
    24→    fn next(&mut self) -> Option<Self::Item> {
    25→        unsafe {
    26→            if self.0.is_null() || (*self.0).is_null() {
    27→                return None;
    28→            }
    29→            let entry = CStr::from_ptr(*self.0);
    30→            self.0 = self.0.add(1);
    31→            Some(entry)
    32→        }
    33→    }
    34→}
    35→
    36→/// Safe iterator over environ entries
    37→fn iter_environ() -> EnvIter {
    38→    EnvIter(unsafe { environ })
    39→}
    40→
    41→/// Get an environment variable by name.
    42→/// Returns pointer to the value (after '=') or null if not found.
    43→///
    44→/// # Safety
    45→/// `name` must be a valid null-terminated C string.
    46→#[unsafe(no_mangle)]
    47→pub unsafe extern "C" fn getenv(name: *const c_char) -> *const c_char {
    48→    if name.is_null() {
    49→        return core::ptr::null();
    50→    }
    51→
    52→    let name_cstr = unsafe { CStr::from_ptr(name) };
    53→    let name_bytes = name_cstr.to_bytes();
    54→
    55→    if name_bytes.is_empty() {
    56→        return core::ptr::null();
    57→    }
    58→
    59→    for entry in iter_environ() {
    60→        let entry_bytes = entry.to_bytes();
    61→        if let Some(rest) = entry_bytes.strip_prefix(name_bytes)
