     2→//!
     3→//! Provides the `environ` symbol and `getenv` function needed by std::env.
     4→
     5→use core::ffi::{CStr, c_char};
     6→
     7→/// Global environment pointer - set during startup by __libc_start_main
     8→#[unsafe(no_mangle)]
     9→pub static mut environ: *const *const c_char = core::ptr::null();
    10→
    11→/// Initialize environ from the environment pointer passed to __libc_start_main
