     1→//! Project automation tasks
     2→//!
     3→//! All commands default to debug builds and verbose output.
     4→//! Use `-r` for release builds, `-q` for quiet output.
     5→//!
     6→//! # Usage
     7→//!
     8→//! ```text
     9→//! cargo xtask build                 # build all crates
    10→//! cargo xtask build ex-x1 -r        # build specific crate (release)
    11→//!
    12→//! cargo xtask run hw-x1             # run specific crate (shows exit code)
    13→//! cargo xtask run .                 # run crate in current directory
    14→//!
    15→//! cargo xtask test                  # test all crates
    16→//! cargo xtask test ex-x1 -q         # test specific crate (quiet)
    17→//! cargo xtask test rlibc-x2         # includes rlibc-x2-tests binaries
    18→//! ```
    19→//!
    20→//! # Available Commands
    21→//!
    22→//! - `build` - Build crates (one at a time)
    23→//! - `run` - Build and run crates (shows exit code)
    24→//! - `test` - Run tests (with summary)
    25→
    26→use std::fs;
    27→use std::path::Path;
    28→use std::process::{Command, ExitCode, Stdio};
    29→
    30→enum Subcommand {
    31→    Build,
    32→    Run,
    33→    Test,
    34→}
    35→
    36→struct Config {
    37→    subcommand: Subcommand,
    38→    quiet: bool,
    39→    fail_fast: bool,
    40→    debug: bool,
    41→    crates: Vec<String>, // Empty means all crates
    42→}
    43→
    44→struct TestResult {
    45→    name: String,
    46→    passed: bool,
    47→    #[allow(dead_code)] // Captured for potential future use (e.g., detailed failure reports)
    48→    output: String,
    49→}
    50→
    51→fn main() -> ExitCode {
    52→    let config = parse_args();
    53→
    54→    // Get workspace root (xtask is at workspace root level)
    55→    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
    56→        .parent()
    57→        .expect("Could not find workspace root");
    58→
    59→    let cmd_name = match config.subcommand {
    60→        Subcommand::Build => "build",
    61→        Subcommand::Run => "run",
    62→        Subcommand::Test => "test",
    63→    };
    64→
    65→    // Get list of crates to operate on
    66→    let crates = if config.crates.is_empty() {
    67→        get_all_crates(workspace_root)
    68→    } else {
    69→        config.crates.clone()
    70→    };
    71→
    72→    // Run command on each crate
    73→    let mut results = Vec::new();
    74→    for crate_name in &crates {
    75→        // Skip lib-only crates for run command
    76→        if cmd_name == "run" && !crate_has_binary(crate_name, workspace_root) {
    77→            continue;
    78→        }
    79→
    80→        let result = run_cargo_on_crate(cmd_name, crate_name, workspace_root, &config);
    81→        let failed = !result.passed;
    82→        results.push(result);
    83→        if failed && config.fail_fast {
    84→            break;
    85→        }
    86→    }
    87→
    88→    // For test, also run rlibc-x2-tests if rlibc-x2 was included
    89→    if matches!(config.subcommand, Subcommand::Test) {
    90→        let should_run_rlibc_x2_tests = if config.crates.is_empty() {
    91→            true // Running all tests
    92→        } else {
    93→            config.crates.iter().any(|c| c == "rlibc-x2")
    94→        };
    95→
    96→        if should_run_rlibc_x2_tests {
    97→            let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, &config);
    98→            for result in rlibc_x2_results {
    99→                let failed = !result.passed;
   100→                results.push(result);
   101→                if failed && config.fail_fast {
   102→                    break;
   103→                }
   104→            }
   105→        }
   106→    }
   107→
   108→    // Only show summary for test command
   109→    if matches!(config.subcommand, Subcommand::Test) {
   110→        print_summary(&results)
   111→    } else {
   112→        // For build/run, just return success/failure based on results
   113→        if results.iter().any(|r| !r.passed) {
   114→            ExitCode::from(1)
   115→        } else {
   116→            ExitCode::SUCCESS
   117→        }
   118→    }
   119→}
   120→
   121→/// Get list of all crates in the workspace (excludes xtask and test crates)
   122→fn get_all_crates(workspace_root: &Path) -> Vec<String> {
   123→    // These are the crates we want to build/run/test
   124→    let crates = [
   125→        "ex-x1",
   126→        "ex-x2",
   127→        "ex-glibc",
   128→        "ex-musl",
   129→        "hw-x1",
   130→        "hw-x2",
   131→        "hw-glibc",
   132→        "hw-musl",
   133→        "rlibc-x1",
   134→        "rlibc-x2",
   135→        "is-libc-used",
   136→    ];
   137→
   138→    // Filter to crates that exist
   139→    crates
   140→        .iter()
   141→        .filter(|name| {
   142→            get_crate_path(name, workspace_root)
   143→                .join("Cargo.toml")
   144→                .exists()
   145→        })
   146→        .map(|s| s.to_string())
   147→        .collect()
   148→}
   149→
   150→/// Get the path to a crate directory
   151→fn get_crate_path(name: &str, workspace_root: &Path) -> std::path::PathBuf {
   152→    if name.starts_with("ex-") || name.starts_with("hw-") {
   153→        workspace_root.join("apps").join(name)
   154→    } else if name == "is-libc-used" {
   155→        workspace_root.join("tools").join(name)
   156→    } else {
   157→        workspace_root.join(name)
   158→    }
   159→}
   160→
   161→/// Check if a crate has a binary (src/main.rs)
   162→fn crate_has_binary(name: &str, workspace_root: &Path) -> bool {
   163→    get_crate_path(name, workspace_root)
   164→        .join("src/main.rs")
   165→        .exists()
   166→}
   167→
   168→/// Run a cargo command on a single crate
   169→fn run_cargo_on_crate(
   170→    cmd_name: &str,
   171→    crate_name: &str,
   172→    workspace_root: &Path,
   173→    config: &Config,
   174→) -> TestResult {
   175→    let is_musl = crate_name.contains("musl");
   176→    let target_info = if is_musl { " (musl)" } else { "" };
   177→
   178→    println!("=== {crate_name}{target_info} ===");
   179→
   180→    let mut cmd = Command::new("cargo");
   181→    cmd.arg(cmd_name);
   182→
   183→    if !config.debug {
   184→        cmd.arg("--release");
   185→    }
   186→
   187→    cmd.args(["-p", crate_name]);
   188→
   189→    if is_musl {
   190→        cmd.args(["--target", "x86_64-unknown-linux-musl"]);
   191→    }
   192→
   193→    cmd.current_dir(workspace_root);
   194→
   195→    if config.quiet {
   196→        cmd.stdout(Stdio::piped());
   197→        cmd.stderr(Stdio::piped());
   198→
   199→        match cmd.output() {
   200→            Ok(output) => {
   201→                let passed = output.status.success();
   202→                let exit_code = output.status.code().unwrap_or(-1);
   203→                let stderr = String::from_utf8_lossy(&output.stderr);
   204→
   205→                if cmd_name == "run" {
   206→                    println!("  exit code: {exit_code}");
   207→                } else if passed {
   208→                    println!("  ok");
   209→                } else {
   210→                    println!("  FAILED");
   211→                    eprintln!("{stderr}");
   212→                }
   213→
   214→                TestResult {
   215→                    name: crate_name.to_string(),
   216→                    passed,
   217→                    output: stderr.to_string(),
   218→                }
   219→            }
   220→            Err(e) => {
   221→                eprintln!("  Failed to run cargo {cmd_name}: {e}");
   222→                TestResult {
   223→                    name: crate_name.to_string(),
   224→                    passed: false,
   225→                    output: e.to_string(),
   226→                }
   227→            }
   228→        }
   229→    } else {
   230→        // Verbose mode - show all output
   231→        let status = cmd.status();
   232→        let (passed, exit_code) = match &status {
   233→            Ok(s) => (s.success(), s.code().unwrap_or(-1)),
   234→            Err(_) => (false, -1),
   235→        };
   236→
   237→        if cmd_name == "run" {
   238→            println!("  exit code: {exit_code}");
   239→        }
   240→        println!();
   241→
   242→        TestResult {
   243→            name: crate_name.to_string(),
   244→            passed,
   245→            output: String::new(),
   246→        }
   247→    }
   248→}
   249→
   250→fn parse_args() -> Config {
   251→    let args: Vec<String> = std::env::args().skip(1).collect();
   252→    let mut args_iter = args.iter();
   253→
   254→    // Parse subcommand (first argument)
   255→    let subcommand = match args_iter.next().map(|s| s.as_str()) {
   256→        Some("build") => Subcommand::Build,
   257→        Some("run") => Subcommand::Run,
   258→        Some("test") => Subcommand::Test,
   259→        Some("-h" | "--help") => {
   260→            print_main_help();
   261→            std::process::exit(0);
   262→        }
   263→        Some(other) => {
   264→            eprintln!("Unknown command: {other}");
   265→            eprintln!("Use --help for usage information");
   266→            std::process::exit(1);
   267→        }
   268→        None => {
   269→            print_main_help();
   270→            std::process::exit(0);
   271→        }
   272→    };
   273→
   274→    let mut config = Config {
   275→        subcommand,
   276→        quiet: false,
   277→        fail_fast: false,
   278→        debug: true, // Default to debug for faster iteration; use -r for release
   279→        crates: Vec::new(),
   280→    };
   281→
   282→    // Parse options and positional arguments for the subcommand
   283→    for arg in args_iter {
   284→        match arg.as_str() {
   285→            "-q" | "--quiet" => config.quiet = true,
   286→            "-f" | "--fail-fast" | "--fail" => config.fail_fast = true,
   287→            "-r" | "--release" => config.debug = false,
   288→            "-d" | "--debug" => config.debug = true,
   289→            "-h" | "--help" => {
   290→                match config.subcommand {
   291→                    Subcommand::Build => print_cmd_help("build"),
   292→                    Subcommand::Run => print_cmd_help("run"),
   293→                    Subcommand::Test => print_test_help(),
   294→                }
   295→                std::process::exit(0);
   296→            }
   297→            other if other.starts_with('-') => {
   298→                eprintln!("Unknown option: {other}");
   299→                eprintln!("Use --help for usage information");
   300→                std::process::exit(1);
   301→            }
   302→            "." => {
   303→                match resolve_current_crate() {
   304→                    Ok(Some(name)) => config.crates.push(name),
   305→                    Ok(None) => {} // Workspace root - leave crates empty for "all"
   306→                    Err(e) => {
   307→                        eprintln!("{e}");
   308→                        std::process::exit(1);
   309→                    }
   310→                }
   311→            }
   312→            crate_name => {
   313→                config.crates.push(crate_name.to_string());
   314→            }
   315→        }
   316→    }
   317→
   318→    config
   319→}
   320→
   321→/// Resolve "." to the crate name in the current directory
   322→/// Returns None if at workspace root (meaning "all"), Some(name) for a crate, or error
   323→fn resolve_current_crate() -> Result<Option<String>, String> {
   324→    let cargo_toml = std::env::current_dir()
   325→        .map_err(|e| format!("Failed to get current directory: {e}"))?
   326→        .join("Cargo.toml");
   327→
   328→    if !cargo_toml.exists() {
   329→        return Err("No Cargo.toml found in current directory".to_string());
   330→    }
   331→
   332→    let content =
