/// Run a cargo command on a single crate
fn run_cargo_on_crate(
    cmd_name: &str,
    crate_name: &str,
    workspace_root: &Path,
    config: &Config,
) -> TestResult {
    let is_musl = crate_name.contains("musl");
    let is_x2 = crate_name.ends_with("-x2");
    let use_rlibcx2 = config.rlibcx2 && is_x2;

    let target_info = if is_musl {
