   244→        // automatically makes all symbols local except the entry point. This would:
   245→        // 1. Enable dead code elimination via --gc-sections
   246→        // 2. Improve security by hiding internal implementation details
   247→        // 3. Reduce binary size by eliminating .dynsym bloat
   248→        // Instead, we must create a "version script" file with arcane syntax!
   249→        // Another short term solution would be to accept the configuration directly:
   250→        //   link-arg=-Wl,--version-script="{ global: _start; local:*; }"
   251→        let target_dir = workspace_root.join("target");
   252→        let _ = fs::create_dir_all(&target_dir);
   253→        let version_config = target_dir.join("rlibcx2-version.config");
   254→        if let Ok(mut f) = fs::File::create(&version_config) {
   255→            let _ = writeln!(f, "{{ global: _start; local: *; }};");
   256→        }
   257→
   258→        cmd.env(
   259→            "RUSTFLAGS",
   260→            format!(
   261→                "-C panic=immediate-abort -Z unstable-options -C link-arg=-Wl,--gc-sections -C link-arg=-Wl,--version-script={}",
   262→                version_config.display()
   263→            ),
   264→        );
   265→        let target_json = workspace_root.join("x86_64-unknown-linux-rlibcx2.json");
   266→        cmd.arg("--target");
   267→        cmd.arg(&target_json);
   268→    }
   269→
   270→    cmd.current_dir(workspace_root);
   271→
   272→    if config.quiet {
   273→        cmd.stdout(Stdio::piped());
   274→        cmd.stderr(Stdio::piped());
   275→
   276→        match cmd.output() {
   277→            Ok(output) => {
   278→                let passed = output.status.success();
   279→                let exit_code = output.status.code().unwrap_or(-1);
   280→                let stderr = String::from_utf8_lossy(&output.stderr);
   281→
   282→                if cmd_name == "run" {
   283→                    println!("  exit code: {exit_code}");
   284→                } else if passed {
   285→                    // Strip binary if requested and build succeeded
   286→                    if config.strip && cmd_name == "build" {
   287→                        strip_binary(crate_name, workspace_root, config);
   288→                    }
   289→                    println!("  ok");
   290→                } else {
   291→                    println!("  FAILED");
   292→                    eprintln!("{stderr}");
   293→                }
   294→
   295→                TestResult {
   296→                    name: crate_name.to_string(),
   297→                    passed,
   298→                    output: stderr.to_string(),
   299→                }
   300→            }
   301→            Err(e) => {
   302→                eprintln!("  Failed to run cargo {cmd_name}: {e}");
   303→                TestResult {
   304→                    name: crate_name.to_string(),
   305→                    passed: false,
   306→                    output: e.to_string(),
   307→                }
   308→            }
   309→        }
   310→    } else {
   311→        // Verbose mode - show all output
   312→        let status = cmd.status();
   313→        let (passed, exit_code) = match &status {
   314→            Ok(s) => (s.success(), s.code().unwrap_or(-1)),
   315→            Err(_) => (false, -1),
   316→        };
   317→
   318→        if cmd_name == "run" {
   319→            println!("  exit code: {exit_code}");
   320→        } else if passed && config.strip && cmd_name == "build" {
   321→            // Strip binary if requested and build succeeded
   322→            strip_binary(crate_name, workspace_root, config);
   323→        }
   324→        println!();
   325→
   326→        TestResult {
   327→            name: crate_name.to_string(),
   328→            passed,
   329→            output: String::new(),
   330→        }
   331→    }
   332→}
   333→
   334→/// Strip debug symbols from the built binary
   335→fn strip_binary(crate_name: &str, workspace_root: &Path, config: &Config) {
   336→    let profile = if config.debug { "debug" } else { "release" };
   337→    let target_subdir = if crate_name.contains("musl") {
   338→        "x86_64-unknown-linux-musl"
   339→    } else if config.rlibcx2 && crate_name.ends_with("-x2") {
   340→        "x86_64-unknown-linux-rlibcx2"
   341→    } else {
   342→        ""
   343→    };
   344→
   345→    let binary_path = if target_subdir.is_empty() {
   346→        workspace_root.join(format!("target/{profile}/{crate_name}"))
   347→    } else {
   348→        workspace_root.join(format!("target/{target_subdir}/{profile}/{crate_name}"))
   349→    };
   350→
   351→    if binary_path.exists() {
   352→        let status = Command::new("strip").arg(&binary_path).status();
   353→        match status {
   354→            Ok(s) if s.success() => {
   355→                if !config.quiet {
   356→                    if let Ok(meta) = fs::metadata(&binary_path) {
   357→                        println!("  stripped: {} bytes", meta.len());
   358→                    }
   359→                }
   360→            }
   361→            _ => {
   362→                eprintln!("  warning: failed to strip {}", binary_path.display());
   363→            }
   364→        }
   365→    }
   366→}
   367→
   368→fn parse_args() -> Config {
   369→    let args: Vec<String> = std::env::args().skip(1).collect();
   370→    let mut args_iter = args.iter();
   371→
   372→    // Parse subcommand (first argument)
   373→    let subcommand = match args_iter.next().map(|s| s.as_str()) {
   374→        Some("build") => Subcommand::Build,
   375→        Some("run") => Subcommand::Run,
   376→        Some("test") => Subcommand::Test,
   377→        Some("-h" | "--help") => {
   378→            print_main_help();
   379→            std::process::exit(0);
   380→        }
   381→        Some(other) => {
   382→            eprintln!("Unknown command: {other}");
   383→            eprintln!("Use --help for usage information");
   384→            std::process::exit(1);
   385→        }
   386→        None => {
   387→            print_main_help();
   388→            std::process::exit(0);
   389→        }
   390→    };
   391→
   392→    let mut config = Config {
   393→        subcommand,
   394→        quiet: false,
   395→        fail_fast: false,
   396→        debug: true, // Default to debug for faster iteration; use -r for release
   397→        rlibcx2: false,
   398→        strip: false,
   399→        crates: Vec::new(),
   400→    };
   401→
   402→    // Parse options and positional arguments for the subcommand
   403→    for arg in args_iter {
   404→        match arg.as_str() {
   405→            "-q" | "--quiet" => config.quiet = true,
   406→            "-f" | "--fail-fast" | "--fail" => config.fail_fast = true,
   407→            "-r" | "--release" => config.debug = false,
   408→            "-d" | "--debug" => config.debug = true,
   409→            "-x2" | "--rlibcx2" => config.rlibcx2 = true,
   410→            "-s" | "--strip" => config.strip = true,
   411→            "-h" | "--help" => {
   412→                match config.subcommand {
   413→                    Subcommand::Build => print_cmd_help("build"),
   414→                    Subcommand::Run => print_cmd_help("run"),
   415→                    Subcommand::Test => print_test_help(),
   416→                }
   417→                std::process::exit(0);
   418→            }
   419→            other if other.starts_with('-') => {
   420→                eprintln!("Unknown option: {other}");
   421→                eprintln!("Use --help for usage information");
   422→                std::process::exit(1);
   423→            }
   424→            "." => {
   425→                match resolve_current_crate() {
   426→                    Ok(Some(name)) => config.crates.push(name),
   427→                    Ok(None) => {} // Workspace root - leave crates empty for "all"
   428→                    Err(e) => {
   429→                        eprintln!("{e}");
   430→                        std::process::exit(1);
   431→                    }
   432→                }
   433→            }
   434→            crate_name => {
   435→                config.crates.push(crate_name.to_string());
   436→            }
   437→        }
   438→    }
   439→
   440→    config
   441→}
   442→
   443→/// Resolve "." to the crate name in the current directory
   444→/// Returns None if at workspace root (meaning "all"), Some(name) for a crate, or error
   445→fn resolve_current_crate() -> Result<Option<String>, String> {
   446→    let cargo_toml = std::env::current_dir()
   447→        .map_err(|e| format!("Failed to get current directory: {e}"))?
   448→        .join("Cargo.toml");
   449→
   450→    if !cargo_toml.exists() {
   451→        return Err("No Cargo.toml found in current directory".to_string());
   452→    }
   453→
   454→    let content =
   455→        fs::read_to_string(&cargo_toml).map_err(|e| format!("Failed to read Cargo.toml: {e}"))?;
   456→
   457→    // Simple parsing - look for name = "..." in [package] section
   458→    let mut in_package = false;
   459→    for line in content.lines() {
   460→        let line = line.trim();
   461→        if line == "[package]" {
   462→            in_package = true;
   463→            continue;
   464→        }
   465→        if line.starts_with('[') {
   466→            in_package = false;
   467→            continue;
   468→        }
   469→        if in_package && line.starts_with("name") {
   470→            // Parse: name = "crate-name"
   471→            if let Some(eq_pos) = line.find('=') {
   472→                let value = line[eq_pos + 1..].trim();
   473→                let value = value.trim_matches('"').trim_matches('\'');
   474→                return Ok(Some(value.to_string()));
   475→            }
   476→        }
   477→    }
   478→
   479→    // No [package] section - likely workspace root, treat as "all"
   480→    Ok(None)
   481→}
   482→
