   538→    println!("  -d, --debug       Use debug builds (default)");
   539→    println!("  -r, --release     Use release builds");
   540→    println!("  -x2, --rlibcx2    Use nightly + build-std + panic-immediate-abort for x2 crates");
   541→    println!("  -s, --strip       Strip debug symbols from binaries after building");
   542→    println!("  -h, --help        Show this help");
   543→    println!();
   544→    println!("Examples:");
   545→    println!("  cargo xtask test              # all tests");
   546→    println!("  cargo xtask test .            # test crate in current directory");
   547→    println!("  cargo xtask test ex-x1        # test ex-x1 only");
   548→    println!("  cargo xtask test ex-musl      # test ex-musl (musl target)");
   549→    println!("  cargo xtask test rlibc-x2     # test rlibc-x2 + rlibc-x2-tests");
   550→    println!("  cargo xtask test hw-x2 -x2    # test hw-x2 with rlibcx2 target");
