   553→fn run_rlibc_x2_tests(workspace_root: &Path, config: &Config) -> Vec<TestResult> {
   554→    let mut results = Vec::new();
   555→
   556→    println!("=== rlibc-x2-tests ===");
   557→
   558→    // First, build the test binaries
   559→    print!("  Building rlibc-x2-tests... ");
   560→
   561→    let mut build_cmd = Command::new("cargo");
   562→    build_cmd.args(["build", "-p", "rlibc-x2-tests"]);
   563→    if !config.debug {
   564→        build_cmd.arg("--release");
   565→    }
   566→    let build_output = build_cmd
   567→        .current_dir(workspace_root)
   568→        .stdout(Stdio::piped())
   569→        .stderr(Stdio::piped())
   570→        .output();
   571→
   572→    match build_output {
   573→        Ok(output) if output.status.success() => {
   574→            println!("ok");
   575→        }
   576→        Ok(output) => {
   577→            println!("FAILED");
   578→            let stderr = String::from_utf8_lossy(&output.stderr);
   579→            eprintln!("{stderr}");
   580→            results.push(TestResult {
   581→                name: "rlibc-x2-tests (build)".to_string(),
   582→                passed: false,
   583→                output: stderr.to_string(),
   584→            });
   585→            return results;
   586→        }
   587→        Err(e) => {
   588→            println!("FAILED");
   589→            eprintln!("  Failed to run cargo build: {e}");
   590→            results.push(TestResult {
   591→                name: "rlibc-x2-tests (build)".to_string(),
   592→                passed: false,
   593→                output: e.to_string(),
   594→            });
   595→            return results;
   596→        }
   597→    }
   598→
   599→    // Find and run test binaries
   600→    let profile = if config.debug { "debug" } else { "release" };
   601→    let target_dir = workspace_root.join(format!("target/{profile}"));
   602→
   603→    let test_binaries: Vec<_> = fs::read_dir(&target_dir)
   604→        .into_iter()
   605→        .flatten()
   606→        .filter_map(|e| e.ok())
   607→        .filter(|e| {
   608→            let name = e.file_name();
   609→            let name = name.to_string_lossy();
   610→            name.ends_with("-tests") && e.path().is_file()
   611→        })
   612→        .collect();
   613→
   614→    if test_binaries.is_empty() {
   615→        eprintln!("  No test binaries found in {}", target_dir.display());
   616→        results.push(TestResult {
   617→            name: "rlibc-x2-tests (no binaries)".to_string(),
   618→            passed: false,
   619→            output: String::new(),
   620→        });
   621→        return results;
   622→    }
   623→
   624→    for entry in test_binaries {
   625→        let path = entry.path();
   626→        let name = entry.file_name();
   627→        let name_str = name.to_string_lossy();
   628→
   629→        print!("  Running {name_str}... ");
   630→
   631→        let output = Command::new(&path)
   632→            .stdout(Stdio::piped())
   633→            .stderr(Stdio::piped())
   634→            .output();
   635→
   636→        match output {
   637→            Ok(output) => {
   638→                let passed = output.status.success();
   639→                let stdout = String::from_utf8_lossy(&output.stdout);
   640→                let stderr = String::from_utf8_lossy(&output.stderr);
   641→                let combined = format!("{stdout}{stderr}");
   642→
   643→                if passed {
   644→                    println!("ok");
   645→                    if !config.quiet && !stdout.is_empty() {
   646→                        println!("{stdout}");
   647→                    }
   648→                } else {
   649→                    println!("FAILED");
   650→                    println!("{combined}");
   651→                }
   652→
   653→                results.push(TestResult {
   654→                    name: format!("rlibc-x2-tests/{name_str}"),
   655→                    passed,
   656→                    output: combined.to_string(),
   657→                });
   658→            }
   659→            Err(e) => {
   660→                println!("FAILED");
   661→                let output = format!("Failed to run: {e}");
   662→                eprintln!("  {output}");
   663→                results.push(TestResult {
   664→                    name: format!("rlibc-x2-tests/{name_str}"),
   665→                    passed: false,
   666→                    output,
   667→                });
   668→            }
   669→        }
   670→    }
   671→
   672→    println!();
   673→    results
   674→}
   675→
   676→fn print_summary(results: &[TestResult]) -> ExitCode {
   677→    println!("========================================");
   678→    println!("               SUMMARY");
   679→    println!("========================================\n");
   680→
   681→    let mut passed_count = 0;
   682→    let mut failed_count = 0;
   683→
   684→    for result in results {
   685→        let status = if result.passed {
   686→            passed_count += 1;
   687→            "PASS"
   688→        } else {
   689→            failed_count += 1;
   690→            "FAIL"
   691→        };
   692→        println!("  [{status}] {}", result.name);
   693→    }
   694→
   695→    println!(
   696→        "\n  Total: {} passed, {} failed",
   697→        passed_count, failed_count
   698→    );
   699→    println!("========================================\n");
   700→
   701→    if failed_count > 0 {
   702→        ExitCode::from(1)
   703→    } else {
   704→        ExitCode::SUCCESS
   705→    }
   706→}
